import random


class FarmPlotAllocationEnv:
    """Allocate a fixed farm budget across three crops with hidden concave
    yield curves, discovered via test plantings, then commit one final split."""

    CROPS = ("wheat", "corn", "soy")
    BUDGET = 12
    MAX_STEPS = 10

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        self.a = {c: self.rng.randint(6, 10) for c in self.CROPS}
        self.b = {c: self.rng.choice([1, 2, 3, 4]) / 10.0 for c in self.CROPS}
        self.steps = 0
        self.tested_crops = set()
        self.done = False
        self.optimal_yield = self._compute_optimal()

        obs = (
            "You manage a farm with a planting budget of "
            f"{self.BUDGET} plot-units to split across three crops: "
            f"{', '.join(self.CROPS)}. Each crop's total yield rises with "
            "more plot-units devoted to it, but the *rate* of increase "
            "changes as you add more units to that same crop.\n\n"
            "Two action forms:\n"
            "  TEST <crop> <amount>   -- see the yield if you devoted "
            "<amount> plot-units (0-12) to <crop> alone (does not spend "
            "your real budget, just a turn).\n"
            "  PLANT <wheat> <corn> <soy>  -- commit final integer "
            "plot-units to each crop (must sum to at most "
            f"{self.BUDGET}); this ends the episode and scores your yield.\n\n"
            f"You have {self.MAX_STEPS} turns total, including any TEST "
            "calls. Use TEST to learn each crop's curve, then PLANT once "
            "you have a strong allocation."
        )
        info = {"budget": self.BUDGET, "crops": self.CROPS}
        return obs, info

    def _yield_for(self, crop, amount):
        a, b = self.a[crop], self.b[crop]
        return a * amount - b * amount * amount

    def _compute_optimal(self):
        best = -1.0
        for w in range(self.BUDGET + 1):
            for c in range(self.BUDGET + 1 - w):
                s = self.BUDGET - w - c
                total = (
                    self._yield_for("wheat", w)
                    + self._yield_for("corn", c)
                    + self._yield_for("soy", s)
                )
                if total > best:
                    best = total
        return best

    def step(self, action):
        if self.done:
            return "Episode already finished.", 0.0, True, False, {}

        reward = 0.0
        terminated = False
        obs = None
        parts = action.strip().split()

        if len(parts) == 3 and parts[0].upper() == "TEST":
            crop = parts[1].lower()
            if crop not in self.CROPS:
                obs = (
                    f"Unrecognized crop '{parts[1]}'. Valid crops: "
                    f"{', '.join(self.CROPS)}."
                )
            else:
                try:
                    amt = int(parts[2])
                except ValueError:
                    amt = None
                if amt is None or amt < 0 or amt > self.BUDGET:
                    obs = (
                        f"Invalid amount '{parts[2]}'. Must be an integer "
                        f"between 0 and {self.BUDGET}."
                    )
                else:
                    y = self._yield_for(crop, amt)
                    self.tested_crops.add(crop)
                    obs = (
                        f"TEST {crop} {amt} -> yield {y:.2f} "
                        "(this was a trial planting; your real budget is "
                        "untouched)."
                    )
        elif len(parts) == 4 and parts[0].upper() == "PLANT":
            try:
                w, c, s = int(parts[1]), int(parts[2]), int(parts[3])
            except ValueError:
                w = c = s = None

            if w is None:
                obs = "Invalid PLANT amounts; use three integers, e.g. PLANT 4 5 3."
            elif w < 0 or c < 0 or s < 0 or (w + c + s) > self.BUDGET:
                obs = (
                    f"Invalid allocation: wheat={w}, corn={c}, soy={s} "
                    f"sums to {w + c + s}, which exceeds your budget of "
                    f"{self.BUDGET} (or contains a negative value)."
                )
            else:
                total_yield = (
                    self._yield_for("wheat", w)
                    + self._yield_for("corn", c)
                    + self._yield_for("soy", s)
                )
                ratio = 0.0
                if self.optimal_yield > 0:
                    ratio = min(1.0, total_yield / self.optimal_yield)
                exploration_bonus = 0.2 if len(self.tested_crops) >= 2 else 0.0
                quality = 0.8 * ratio
                reward = exploration_bonus + quality
                terminated = True
                self.done = True
                obs = (
                    f"PLANT {w} {c} {s} -> total yield {total_yield:.2f} "
                    f"(best possible was {self.optimal_yield:.2f}, "
                    f"{ratio * 100:.1f}% of optimal). Harvest complete."
                )
        else:
            obs = (
                "Malformed action. Use 'TEST <crop> <amount>' or "
                "'PLANT <wheat> <corn> <soy>'."
            )

        self.steps += 1
        truncated = False
        if not terminated and self.steps >= self.MAX_STEPS:
            truncated = True
            obs += " No PLANT was committed before the step limit; season over with 0 yield scored."

        info = {"steps": self.steps, "optimal_yield": self.optimal_yield}
        return obs, reward, terminated, truncated, info

import random


class MosaicBorderEnv:
    ALPHABET = ['A', 'B', 'C', 'D']
    BORDER_LEN = 20
    WINDOW_LEN = 7
    TARGET_START = 7
    TARGET_LEN = 4
    MAX_STEPS = 10

    def _generate_border(self, motif, L, mode, length):
        border = []
        for i in range(length):
            block = i // L
            j = i % L
            if mode == 'repeat':
                symbol = motif[j]
            else:
                symbol = motif[j] if block % 2 == 0 else motif[L - 1 - j]
            border.append(symbol)
        return border

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        self.L = self.rng.choice([3, 4, 5])
        while True:
            motif = [self.rng.choice(self.ALPHABET) for _ in range(self.L)]
            if len(set(motif)) >= 2 and motif != motif[::-1]:
                break
        self.motif = motif
        self.mode = self.rng.choice(['repeat', 'mirror'])
        self.border = self._generate_border(motif, self.L, self.mode, self.BORDER_LEN)
        self.window = self.border[:self.WINDOW_LEN]
        self.target = self.border[self.TARGET_START:self.TARGET_START + self.TARGET_LEN]
        self.steps = 0
        self.done = False
        self.length_reward_given = False

        window_str = " ".join("{}:{}".format(i, s) for i, s in enumerate(self.window))
        target_lo = self.TARGET_START
        target_hi = self.TARGET_START + self.TARGET_LEN - 1
        obs = (
            "MOSAIC BORDER. Tiles are single letters from {A,B,C,D} arranged left to "
            "right by index. The first {wlen} tiles (indices 0-{wmax}) are:\n"
            "{window}\n"
            "A hidden rule extends this border forever. Indices {tlo}-{thi} are masked "
            "and must be predicted. You have up to {maxs} total actions.\n"
            "Actions (send exactly one per turn):\n"
            "  PEEK <index>            reveal the tile at a chosen index (0-{bmax}); "
            "the masked target range {tlo}-{thi} cannot be peeked.\n"
            "  GUESS_LENGTH <n>        guess the hidden motif length (an integer, "
            "typically small); a correct guess earns partial credit once.\n"
            "  EXTEND <s1> <s2> <s3> <s4>   submit your final 4-letter prediction for "
            "indices {tlo},{tlo1},{tlo2},{thi} in order (space-separated single "
            "letters); this ends the episode.\n"
            "Reward: 0.3 for a correct GUESS_LENGTH, plus up to 0.7 for EXTEND scaled "
            "by how many of the 4 predicted tiles are correct."
        ).format(
            wlen=self.WINDOW_LEN, wmax=self.WINDOW_LEN - 1, window=window_str,
            tlo=target_lo, thi=target_hi, tlo1=target_lo + 1, tlo2=target_lo + 2,
            maxs=self.MAX_STEPS, bmax=self.BORDER_LEN - 1,
        )
        return obs, {}

    def _corrective(self, msg, reward=0.0):
        terminated = False
        truncated = self.steps >= self.MAX_STEPS
        if truncated:
            self.done = True
        return msg, reward, terminated, truncated, {}

    def step(self, action):
        if self.done:
            return "Episode already ended.", 0.0, True, False, {}
        self.steps += 1
        text = (action or "").strip()
        parts = text.split()

        if not parts:
            return self._corrective(
                "Empty action. Use PEEK <index>, GUESS_LENGTH <n>, or EXTEND <4 letters>."
            )

        cmd = parts[0].upper()

        if cmd == "PEEK":
            if len(parts) != 2 or not parts[1].lstrip('-').isdigit():
                return self._corrective("Malformed PEEK. Format: PEEK <index>.")
            idx = int(parts[1])
            lo, hi = self.TARGET_START, self.TARGET_START + self.TARGET_LEN - 1
            if idx < 0 or idx >= self.BORDER_LEN:
                return self._corrective(
                    "Index out of range 0-{}.".format(self.BORDER_LEN - 1)
                )
            if lo <= idx <= hi:
                return self._corrective(
                    "Index {} is inside the masked target range {}-{}; it cannot be peeked.".format(idx, lo, hi)
                )
            return self._corrective("Tile at index {} is {}.".format(idx, self.border[idx]))

        if cmd == "GUESS_LENGTH":
            if len(parts) != 2 or not parts[1].lstrip('-').isdigit():
                return self._corrective("Malformed GUESS_LENGTH. Format: GUESS_LENGTH <n>.")
            n = int(parts[1])
            if n == self.L:
                if self.length_reward_given:
                    return self._corrective("Correct length, but credit was already given.")
                self.length_reward_given = True
                return self._corrective("Correct! The motif length is confirmed.", reward=0.3)
            return self._corrective("That is not the correct motif length.")

        if cmd == "EXTEND":
            tokens = parts[1:]
            if len(tokens) != self.TARGET_LEN or any(
                len(t) != 1 or t.upper() not in self.ALPHABET for t in tokens
            ):
                return self._corrective(
                    "Malformed EXTEND. Provide exactly {} single letters from {{A,B,C,D}}, "
                    "space-separated.".format(self.TARGET_LEN)
                )
            guess = [t.upper() for t in tokens]
            correct = sum(1 for g, t in zip(guess, self.target) if g == t)
            reward = 0.7 * correct / self.TARGET_LEN
            self.done = True
            obs = "EXTEND submitted: {}/{} tiles correct. Episode ended.".format(
                correct, self.TARGET_LEN
            )
            return obs, reward, True, False, {"correct_tiles": correct}

        return self._corrective(
            "Unrecognized command '{}'. Use PEEK, GUESS_LENGTH, or EXTEND.".format(parts[0])
        )

import random


class BracketSeedingEnv:
    TEAMS = ["A", "B", "C", "D", "E", "F", "G", "H"]

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        self.teams = list(self.TEAMS)
        values = list(range(1, 9))
        self.rng.shuffle(values)
        self.strength = dict(zip(self.teams, values))
        self.rank_order = sorted(self.teams, key=lambda t: -self.strength[t])
        self.canonical_slot_rank = self._seed_order(8)
        self.step_count = 0
        self.max_steps = 10
        self.done = False
        obs = self._opening_observation()
        info = {"teams": list(self.teams), "max_steps": self.max_steps}
        return obs, info

    def _seed_order(self, n):
        order = [1]
        size = 1
        while size < n:
            new_order = []
            for s in order:
                new_order.append(s)
                new_order.append(size * 2 + 1 - s)
            order = new_order
            size *= 2
        return order

    def _opening_observation(self):
        return (
            "You are seeding an 8-team single-elimination bracket: teams "
            f"{', '.join(self.teams)}. Bracket slots are numbered 0-7. "
            "Round 1 pairs are (0v1),(2v3),(4v5),(6v7). The Round-1 winners "
            "from slots 0-3 meet in a Round-2 match, and separately the "
            "Round-1 winners from slots 4-7 meet in a Round-2 match. Those "
            "two Round-2 winners meet in the Final. Every team has a hidden "
            "true strength. Two strong teams meeting early creates upset "
            "risk that a good seeding should avoid.\n\n"
            "Your goal: assign all 8 teams to slots 0-7 to minimize the "
            "risk of strong teams eliminating each other before the Final.\n\n"
            "Actions (send exactly one per turn):\n"
            "  SCOUT <team> <team> - watch a practice match between two "
            "teams; you learn which one is stronger.\n"
            "  SEED <t0> <t1> <t2> <t3> <t4> <t5> <t6> <t7> - final "
            "assignment of teams to slots 0..7, in order. This ends the "
            "episode.\n"
            f"You have {self.max_steps} total actions; SCOUT and SEED both "
            "count toward the limit. SEED is your one final submission, so "
            "use SCOUT first to gather evidence."
        )

    def step(self, action):
        if self.done:
            return ("Episode already ended.", 0.0, True, False, {})

        self.step_count += 1
        tokens = action.strip().split() if action else []
        reward = 0.0
        terminated = False
        obs = ""

        if not tokens:
            obs = "Empty action. Use 'SCOUT <team> <team>' or 'SEED <8 teams>'."
        else:
            cmd = tokens[0].upper()
            if cmd == "SCOUT":
                obs = self._do_scout(tokens)
            elif cmd == "SEED":
                obs, reward, terminated = self._do_seed(tokens)
            else:
                obs = "Unknown action. Use 'SCOUT <team> <team>' or 'SEED <8 teams>'."

        truncated = (not terminated) and (self.step_count >= self.max_steps)
        self.done = terminated or truncated
        if truncated and not terminated:
            obs += " No SEED was submitted in time; episode truncated with no reward."
        info = {"step": self.step_count, "remaining_steps": max(0, self.max_steps - self.step_count)}
        return obs, reward, terminated, truncated, info

    def _do_scout(self, tokens):
        if len(tokens) != 3:
            return "SCOUT requires exactly two team letters, e.g. 'SCOUT A B'."
        t1, t2 = tokens[1].upper(), tokens[2].upper()
        if t1 not in self.teams or t2 not in self.teams or t1 == t2:
            return f"Invalid team names. Choose two distinct teams from {', '.join(self.teams)}."
        if self.strength[t1] > self.strength[t2]:
            winner, loser = t1, t2
        else:
            winner, loser = t2, t1
        return f"Scouting result: Team {winner} defeated Team {loser} in a practice match ({winner} is confirmed stronger)."

    def _do_seed(self, tokens):
        if len(tokens) != 9:
            return ("SEED requires exactly 8 team letters, one per slot 0..7.", 0.0, False)
        perm = [x.upper() for x in tokens[1:]]
        if sorted(perm) != sorted(self.teams):
            return ("SEED must be a permutation of all 8 teams with no repeats.", 0.0, False)

        slot_of = {team: idx for idx, team in enumerate(perm)}
        top2 = self.rank_order[:2]
        halves = {(0 if slot_of[t] < 4 else 1) for t in top2}
        score1 = 0.3 if len(halves) == 2 else 0.0

        top4 = self.rank_order[:4]
        quarters = {slot_of[t] // 2 for t in top4}
        score2 = 0.3 if len(quarters) == 4 else 0.0

        rank_of = {team: i + 1 for i, team in enumerate(self.rank_order)}
        matches = sum(
            1 for slot in range(8)
            if rank_of[perm[slot]] == self.canonical_slot_rank[slot]
        )
        score3 = 0.4 * matches / 8

        reward = score1 + score2 + score3
        obs = (
            f"Final seeding submitted: {' '.join(perm)}.\n"
            f"Top-2 kept in separate halves: {'yes' if score1 else 'no'} (+{score1:.2f})\n"
            f"Top-4 spread across four quarters: {'yes' if score2 else 'no'} (+{score2:.2f})\n"
            f"Slots matching the strength-optimal order: {matches}/8 (+{score3:.2f})\n"
            f"Total reward: {reward:.2f}"
        )
        return obs, reward, True


BracketSeedingEnv.__name__ = "BracketSeedingEnv"
